var i=[{title:`Odczytywanie proporcji`,text:`Interwał 1:3 może oznaczać 20 sekund wysiłku i 60 sekund odpoczynku, interwał 1:1 po 30 sekund każdego, a 2:1 to 40 sekund pracy i 20 sekund łatwo. Sama proporcja nie opisuje treningu, dopóki nie znasz czasu trwania i intensywności.`},{title:`Długi odpoczynek dla jakości`,text:`Dość długie przerwy pomagają utrzymać prędkość lub moc w krótkich ciężkich wysiłkach. Układ 1:3 może pasować komuś, kto ćwiczy szybszy bieg lub wymagający ruch i chce uniknąć szybkiego zmęczenia. Bardzo intensywny sprint może wymagać znacznie więcej odpoczynku niż 1:3, by utrzymać wydajność.`},{title:`Równy lub krótki odpoczynek`,text:`Przy 1:1 praca i odpoczynek trwają tyle samo. Przy 2:1 odpoczynek jest krótszy, więc zmęczenie może szybko narastać. Te formaty mogą działać w umiarkowanych obwodach, ale nie są automatycznie lepsze dla zaawansowanych celów wytrzymałościowych czy siłowych.`},{title:`Dostosuj do możliwości i ćwiczenia`,text:`Początkujący może maszerować szybko przez 30 sekund i spokojnie przez 90 sekund, a potem powoli wydłużać pracę. Wytrenowany kolarz może używać dłuższych ciężkich wysiłków z hojnym odpoczynkiem. Ruchy ze skokami często wymagają większej kontroli technicznej, więc wybierz odpoczynek, który utrzymuje dobre lądowania. Oceniaj postęp tym, czy kończysz z dobrą techniką, wydłużaj odpoczynek, gdy go potrzebujesz, i nie utrudniaj każdego interwału tylko po to, by skrócić trening.`}];var a=[{label:`ACE: projektowanie interwałów o wysokiej intensywności`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`CDC: pomiar intensywności wysiłku i test mowy`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`CDC: zalecenia dotyczące aktywności fizycznej dorosłych`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var t={sections:i,sources:a};export{t as default,i as sections,a as sources};